reference_solution:
def searchRange(nums, target):
    def lower(t):
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < t:
                lo = mid + 1
            else:
                hi = mid
        return lo
    a = lower(target)
    if a == len(nums) or nums[a] != target:
        return [-1, -1]
    return [a, lower(target + 1) - 1]

brute_force_solution:
def searchRange(nums, target):
    idx = [i for i, x in enumerate(nums) if x == target]
    return [idx[0], idx[-1]] if idx else [-1, -1]

